cache, db_hits, reqs = {}, 0, 0
for t in range(0, 3600, 10):
    for u in range(1000):
        reqs += 1
        e = cache.get(u)
        if e is None or e <= t:
            db_hits += 1
            cache[u] = t + 300
print(reqs, db_hits, round(db_hits / reqs * 100, 1))  # 360000 12000 3.3
